<script setup lang="ts">
import type { ExecutionData } from '../../../../../packages/contracts/v2/plans/generated'
import { actionLabels,statusLabels } from './presentation'
defineProps<{execution:ExecutionData;readonly?:boolean;confirmations?:Record<string,boolean>;canComplete?:(key:string)=>boolean}>()
const emit=defineEmits<{complete:[key:string];confirm:[key:string,checked:boolean]}>()
</script>
<template><div class="tasks"><article v-for="task in execution.proposal.effective_draft.tasks" :key="task.task_key"><div class="task-heading"><h4>{{ task.title }}</h4><span :data-testid="`plan-task-status-${task.task_key}`">{{ execution.completed_tasks.some(c=>c.task_key===task.task_key)?'本人自报完成':statusLabels[execution.proposal.schedule?.tasks.find(t=>t.task_key===task.task_key)?.status??'draft'] }}</span></div><p>{{ actionLabels[task.action_code] }} · 估时 {{ task.estimated_hours===null?'未知':task.estimated_hours+' 小时' }} · {{ task.estimate_source==='user_adjusted'?'本人调整':task.estimate_source==='unknown'?'未提供':'可修改模板' }}</p><p>验收条件：{{ task.acceptance_criteria }}</p><p v-for="record in execution.completed_tasks.filter(c=>c.task_key===task.task_key)" :key="record.completed_state_version" :data-testid="`plan-completion-${task.task_key}`">本人自报 student_declared · {{ record.completed_at }} · 状态 v{{ record.completed_state_version }}</p><p v-if="task.assessment_key">实得记录：{{ task.assessment_key }} · {{ task.unit??'单位未知' }} · 满分 {{ task.scale??'未知' }}</p><p v-if="task.dependency_keys.length">前置任务：{{ task.dependency_keys.map(key=>execution.proposal.effective_draft.tasks.find(t=>t.task_key===key)?.title??key).join('、') }}</p><template v-if="!readonly&&execution.state==='confirmed'&&!execution.completed_tasks.some(c=>c.task_key===task.task_key)"><label class="check"><input type="checkbox" :checked="confirmations?.[task.task_key]??false" :data-testid="`plan-task-confirm-${task.task_key}`" :disabled="!canComplete?.(task.task_key)" @change="emit('confirm',task.task_key,($event.target as HTMLInputElement).checked)"><span>我声明已达到上列验收条件；这不是成绩、学校结果或资格确认。</span></label><button type="button" :data-testid="`plan-task-complete-${task.task_key}`" :disabled="!canComplete?.(task.task_key)||!confirmations?.[task.task_key]" @click="emit('complete',task.task_key)">记录本人完成</button></template></article></div></template>
<style scoped>
.tasks{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.tasks article{min-width:0;padding:19px;border:1px solid #dce5d5;border-radius:8px;background:#fff}.task-heading{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}h4{font-size:13px;line-height:1.8;margin:0}.task-heading span{font-size:9px;color:#849574;border:1px solid #d9e5cc;padding:4px 7px;border-radius:4px}p{font-size:11px;line-height:1.9;color:#78866e;overflow-wrap:anywhere}.check{display:flex;gap:9px;font-size:10px;line-height:1.9;margin:17px 0}.check input{width:17px;height:17px;flex:0 0 17px;margin:2px 0 0}.check span{min-width:0}button{font-size:11px;border:1px solid #bfceb6;padding:10px 13px;background:#fff;color:#4c7047;border-radius:6px}button:disabled{background:#f0f3eb;color:#929b89}@media(max-width:650px){.tasks{grid-template-columns:1fr}}
</style>
